    // 最终单条查询同时绑定 FAQ 根、当前所有者与全部叶来源，避免跨异步等待沿用旧资格。
    private static string Current(bool mysql, bool scoped)
    {
        var keys = mysql ? "JSON_TABLE(@FaqBindingsJson,'$[*]' COLUMNS (Id CHAR(36) PATH '$.id',SourceHash VARCHAR(64) PATH '$.sourceHash',HeadRevisionId CHAR(36) PATH '$.headRevisionId',HeadVersion INT PATH '$.headVersion')) AS expected"
            : "OPENJSON(@FaqBindingsJson) WITH (Id uniqueidentifier '$.id',SourceHash varchar(64) '$.sourceHash',HeadRevisionId uniqueidentifier '$.headRevisionId',HeadVersion int '$.headVersion') AS expected";
        string Id(string column) => mysql ? "UUID_TO_BIN(" + column + ",0)" : column;
        return "SELECT f.Id FROM fn_ai_knowledge_faq AS f INNER JOIN fn_ai_knowledge_base AS k ON k.Id=f.KnowledgeBaseId INNER JOIN " + keys
            + " ON f.Id=" + Id("expected.Id") + " AND f.SourceHash=expected.SourceHash AND f.HeadRevisionId=" + Id("expected.HeadRevisionId") + " AND f.HeadVersion=expected.HeadVersion"
            + " WHERE f.KnowledgeBaseId=@KnowledgeBaseId AND k.OwnerUserId=@OwnerUserId AND k.IsEnabled=1 AND " + (scoped ? "f.TenantId=@TenantId AND k.TenantId=@TenantId" : "f.TenantId IS NULL AND k.TenantId IS NULL")
            + " AND " + ReadableLeaves(mysql, scoped) + " AND " + AiKnowledgeFaqParentSql.Current(mysql, scoped)
            + " AND " + AiKnowledgeFaqFeedbackSql.Current(mysql, scoped, "f.SourceJson", "f.OriginKey", "k.DataClassification");
    }

    /// <summary>FAQ 最后资源查询和草稿门禁共用完整叶身份/权限谓词；不读取或返回叶正文。</summary>
    internal static string ReadableLeaves(bool mysql, bool scoped)
    {
        var fields = new[] { "KnowledgeBaseId", "DocumentId", "VersionId", "FileId", "TaskId", "PublicationId" };
        var definitions = fields.Select(field => mysql ? field + " CHAR(36) PATH '$." + char.ToLowerInvariant(field[0]) + field[1..] + "'" : field + " uniqueidentifier '$." + char.ToLowerInvariant(field[0]) + field[1..] + "'").ToList();
        foreach (var field in new[] { "ContentHash", "ReceiptHash", "ManifestHash", "PlanHash" }) definitions.Add(field + (mysql ? " VARCHAR(64) PATH '$." : " varchar(64) '$.") + char.ToLowerInvariant(field[0]) + field[1..] + "'");
        foreach (var field in new[] { "DocumentVersion", "KnowledgeBaseVersion" }) definitions.Add(field + (mysql ? " INT PATH '$." : " int '$.") + char.ToLowerInvariant(field[0]) + field[1..] + "'");
        // 损坏 JSON 不应使未选中的条目在查询优化阶段抛 SQL 错误；空替身不构成授权，外层仍核证原 JSON 摘要和协议。
        var safe = mysql ? "CASE WHEN JSON_VALID(f.SourceJson)=1 THEN f.SourceJson ELSE '{\"dependencies\":[]}' END"
            : "CASE WHEN ISJSON(f.SourceJson)=1 THEN f.SourceJson ELSE N'{\"dependencies\":[]}' END";
        var dependencies = mysql ? "JSON_TABLE(" + safe + ",'$.dependencies[*]' COLUMNS (" + string.Join(',', definitions) + ")) AS dependency" : "OPENJSON(" + safe + ",'$.dependencies') WITH (" + string.Join(',', definitions) + ") AS dependency";
        string Id(string column) => mysql ? "UUID_TO_BIN(" + column + ",0)" : column;
        var matches = string.Join(" AND ", fields.Select(field => "source." + field + "=" + Id("dependency." + field)))
            + " AND source.DocumentVersion=dependency.DocumentVersion AND source.KnowledgeBaseVersion=dependency.KnowledgeBaseVersion AND source.ContentHash=dependency.ContentHash"
            + " AND source.ActiveTaskId=" + Id("dependency.TaskId") + " AND source.ActiveLeaseToken IS NOT NULL AND source.ActiveLeaseToken<>" + (mysql ? "UNHEX('00000000000000000000000000000000')" : "CAST('00000000-0000-0000-0000-000000000000' AS uniqueidentifier)")
            + " AND source.ActiveReceiptHash=dependency.ReceiptHash AND source.ActiveManifestHash=dependency.ManifestHash AND source.ActivePlanHash=dependency.PlanHash"
            + " AND source.IsDeleted=0 AND source.CleanupPending=0 AND source.IsCurrent=1 AND source.StateKey='completed' AND source.HasDerivedData=1";
        var sources = AiKnowledgePublishedSourceSql.Readable(mysql, scoped);
        return "NOT EXISTS (SELECT 1 FROM " + dependencies + " WHERE NOT EXISTS (SELECT 1 FROM (" + sources + ") AS source WHERE " + matches + "))";
    }
    private static readonly SqlStatement CurrentSqlServerHost = new("ai.knowledge_faq.current_sqlserver_host", Current(false, false), SqlDataScope.HostOnly);
    private static readonly SqlStatement CurrentSqlServerTenant = new("ai.knowledge_faq.current_sqlserver_tenant", Current(false, true), SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private static readonly SqlStatement CurrentMySqlHost = new("ai.knowledge_faq.current_mysql_host", Current(true, false), SqlDataScope.HostOnly);
    private static readonly SqlStatement CurrentMySqlTenant = new("ai.knowledge_faq.current_mysql_tenant", Current(true, true), SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static SqlStatement CurrentFor(DatabaseProvider provider, bool tenant) => provider == DatabaseProvider.MySql ? tenant ? CurrentMySqlTenant : CurrentMySqlHost : tenant ? CurrentSqlServerTenant : CurrentSqlServerHost;
    // 导出还冻结根分类版本，防止完整载荷等待期间切换为宿主禁止导出的分类。
    private static string ExportCurrent(bool mysql, bool scoped) => Current(mysql, scoped) + " AND k.Version=@TransferKnowledgeVersion AND k.DataClassification=@TransferClassification";
    private static readonly SqlStatement ExportCurrentSqlServerHost = new("ai.knowledge_faq.export_current_sqlserver_host", ExportCurrent(false, false), SqlDataScope.HostOnly);
    private static readonly SqlStatement ExportCurrentSqlServerTenant = new("ai.knowledge_faq.export_current_sqlserver_tenant", ExportCurrent(false, true), SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private static readonly SqlStatement ExportCurrentMySqlHost = new("ai.knowledge_faq.export_current_mysql_host", ExportCurrent(true, false), SqlDataScope.HostOnly);
    private static readonly SqlStatement ExportCurrentMySqlTenant = new("ai.knowledge_faq.export_current_mysql_tenant", ExportCurrent(true, true), SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static SqlStatement ExportCurrentFor(DatabaseProvider provider, bool scoped) => provider == DatabaseProvider.MySql ? scoped ? ExportCurrentMySqlTenant : ExportCurrentMySqlHost : scoped ? ExportCurrentSqlServerTenant : ExportCurrentSqlServerHost;

    private static string SharedCurrent(bool mysql, bool scoped) => Current(mysql, scoped).Replace("k.OwnerUserId=@OwnerUserId", AiKnowledgeFaqReadSql.AudienceForRoot(mysql, scoped), StringComparison.Ordinal);
    private static readonly SqlStatement SharedCurrentSqlServerHost = new("ai.knowledge_faq.shared_current_sqlserver_host", SharedCurrent(false, false), SqlDataScope.HostOnly);
    private static readonly SqlStatement SharedCurrentSqlServerTenant = new("ai.knowledge_faq.shared_current_sqlserver_tenant", SharedCurrent(false, true), SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private static readonly SqlStatement SharedCurrentMySqlHost = new("ai.knowledge_faq.shared_current_mysql_host", SharedCurrent(true, false), SqlDataScope.HostOnly);
    private static readonly SqlStatement SharedCurrentMySqlTenant = new("ai.knowledge_faq.shared_current_mysql_tenant", SharedCurrent(true, true), SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static SqlStatement SharedCurrentFor(DatabaseProvider provider, bool scoped) => provider == DatabaseProvider.MySql ? scoped ? SharedCurrentMySqlTenant : SharedCurrentMySqlHost : scoped ? SharedCurrentSqlServerTenant : SharedCurrentSqlServerHost;
}
